#ifndef ZONOTOPE_H
#define ZONOTOPE_H

// N_STATE/N_INPUT/N_MEAS/MAX_GEN/REDUCTION_BUDGET/RANDOM_SEED/DT/noise radii
// come from the single-source config: config/zonotope_params.json ->
// (generated by tools/gen_zonotope_params.py) -> include/zonotope_params.hpp.
// Edit the JSON, not this file, to change dimensions/budgets.
#include "zonotope_params.hpp"

#ifndef NUM_STEPS
#define NUM_STEPS             100
#endif

using data_t = float;

struct Zonotope {
    int n;
    int m;
    data_t p[N_STATE];
    data_t H[N_STATE][MAX_GEN];
};

enum LambdaMethod {
    LAMBDA_FIXED_GAIN = 0,
    LAMBDA_SEGMENT,
    LAMBDA_VOLUME,
    LAMBDA_P_RADIUS
};

void compute_lambda_segment(data_t lambda[N_STATE], const data_t H[N_STATE][MAX_GEN], int m, const data_t c[N_STATE], data_t phi);
void compute_lambda_volume(data_t lambda[N_STATE], const data_t H[N_STATE][MAX_GEN], int m, const data_t c[N_STATE], data_t phi);
void compute_lambda_p_radius(data_t lambda[N_STATE], const data_t H[N_STATE][MAX_GEN], int m, const data_t c[N_STATE], data_t phi);
void zonotope_reduce(Zonotope* Z, int max_gens);

#endif
